CREATE OR REPLACE FUNCTION public.admin_get_yorp_sample_dataset_status(_session_token text, _batch_name text DEFAULT 'PCYDO-YORP-2024-2026'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'storage', 'extensions'
AS $function$
DECLARE
  _admin_id uuid;
  _test_environment boolean;
  _organizations integer := 0;
  _year_2024 integer := 0;
  _year_2025 integer := 0;
  _year_2026 integer := 0;
  _awaiting integer := 0;
  _released integer := 0;
  _completed integer := 0;
  _liquidated integer := 0;
  _packets integer := 0;
  _documents integer := 0;
  _complete integer := 0;
  _missing integer := 0;
  _duplicates integer := 0;
  _required integer := 0;
  _mapped integer := 0;
  _last_seeded timestamptz;
BEGIN
  SELECT vat.admin_id INTO _admin_id
  FROM public.validate_admin_session_token(_session_token) vat
  JOIN public.admin_accounts aa ON aa.id = vat.admin_id AND aa.is_active
  JOIN public.roles r ON r.id = aa.role_id
  WHERE r.code::text = 'super_admin'
  LIMIT 1;
  IF _admin_id IS NULL THEN
    RAISE EXCEPTION 'A valid Super Admin session is required.' USING ERRCODE = '42501';
  END IF;
  IF _batch_name IS DISTINCT FROM 'PCYDO-YORP-2024-2026' THEN
    RAISE EXCEPTION 'Status is restricted to batch PCYDO-YORP-2024-2026.';
  END IF;
  _test_environment := public.is_development_or_test_environment();

  SELECT count(*), count(*) FILTER (WHERE seed_source_year = 2024),
         count(*) FILTER (WHERE seed_source_year = 2025), count(*) FILTER (WHERE seed_source_year = 2026),
         max(updated_at)
  INTO _organizations, _year_2024, _year_2025, _year_2026, _last_seeded
  FROM public.organization_profiles
  WHERE is_seeded_sample_data IS TRUE AND seed_batch = _batch_name
    AND id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
    AND coalesce(is_renewal_test_account, false) IS FALSE;

  SELECT count(*) FILTER (WHERE br.status = 'awaiting_release'),
         count(*) FILTER (WHERE br.status = 'budget_released'),
         count(*) FILTER (WHERE br.status = 'completed')
  INTO _awaiting, _released, _completed
  FROM public.budget_requests br
  JOIN public.organization_profiles op ON op.id = br.organization_id
  WHERE br.is_seeded_sample_data IS TRUE AND br.seed_batch = _batch_name
    AND op.is_seeded_sample_data IS TRUE AND op.seed_batch = _batch_name
    AND coalesce(op.is_renewal_test_account, false) IS FALSE;

  SELECT count(*) INTO _liquidated
  FROM public.liquidation_reports lr
  JOIN public.organization_profiles op ON op.id = lr.organization_id
  WHERE lr.is_seeded_sample_data IS TRUE AND lr.seed_batch = _batch_name
    AND lr.status = 'completed_liquidated'
    AND op.is_seeded_sample_data IS TRUE AND op.seed_batch = _batch_name
    AND coalesce(op.is_renewal_test_account, false) IS FALSE;

  SELECT count(*) INTO _required
  FROM public.required_document_types rdt
  WHERE rdt.is_active IS TRUE AND coalesce(rdt.is_required, true) IS TRUE
    AND coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
    AND (rdt.scope IS NULL OR rdt.scope IN ('registration', 'both'))
    AND (rdt.template_category IS NULL OR rdt.template_category = '{}' OR 'yorp' = ANY(rdt.template_category));

  SELECT count(*) INTO _mapped
  FROM public.required_document_types rdt
  JOIN public.yorp_sample_document_assets asset ON asset.document_type_id = rdt.id
  JOIN storage.objects object_row ON object_row.bucket_id = asset.bucket_id AND object_row.name = asset.object_name
  WHERE rdt.is_active IS TRUE AND coalesce(rdt.is_required, true) IS TRUE
    AND coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
    AND (rdt.scope IS NULL OR rdt.scope IN ('registration', 'both'))
    AND (rdt.template_category IS NULL OR rdt.template_category = '{}' OR 'yorp' = ANY(rdt.template_category));

  WITH seeded AS (
    SELECT id organization_id FROM public.organization_profiles
    WHERE is_seeded_sample_data IS TRUE AND seed_batch = _batch_name
      AND id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
      AND coalesce(is_renewal_test_account, false) IS FALSE
  ), required AS (
    SELECT id FROM public.required_document_types rdt
    WHERE rdt.is_active IS TRUE AND coalesce(rdt.is_required, true) IS TRUE
      AND coalesce(rdt.template_scope, 'document_submission') = 'document_submission'
      AND (rdt.scope IS NULL OR rdt.scope IN ('registration', 'both'))
      AND (rdt.template_category IS NULL OR rdt.template_category = '{}' OR 'yorp' = ANY(rdt.template_category))
  ), packets AS (
    SELECT s.organization_id, ds.id submission_id
    FROM seeded s JOIN public.document_submissions ds ON ds.organization_id = s.organization_id
    WHERE ds.renewal_id IS NULL AND (ds.submission_scope IS NULL OR ds.submission_scope = 'registration')
  ), counts AS (
    SELECT p.organization_id, r.id document_type_id, count(dsf.id) file_count
    FROM packets p CROSS JOIN required r
    LEFT JOIN public.document_submission_files dsf
      ON dsf.submission_id = p.submission_id AND dsf.document_type_id = r.id
    GROUP BY p.organization_id, r.id
  ), per_org AS (
    SELECT organization_id,
      count(*) FILTER (WHERE file_count = 0) missing_count,
      sum(greatest(file_count - 1, 0)) duplicate_count,
      count(*) FILTER (WHERE file_count = 1) complete_count
    FROM counts GROUP BY organization_id
  )
  SELECT count(*) FILTER (WHERE missing_count = 0 AND duplicate_count = 0 AND complete_count = _required),
         coalesce(sum(missing_count), 0), coalesce(sum(duplicate_count), 0)
  INTO _complete, _missing, _duplicates FROM per_org;

  SELECT count(DISTINCT ds.id), count(dsf.id)
  INTO _packets, _documents
  FROM public.document_submissions ds
  JOIN public.organization_profiles op ON op.id = ds.organization_id
  LEFT JOIN public.document_submission_files dsf ON dsf.submission_id = ds.id
  WHERE op.is_seeded_sample_data IS TRUE AND op.seed_batch = _batch_name
    AND op.id <> '8170959f-2bb8-40ea-8ce8-31deb514de17'::uuid
    AND coalesce(op.is_renewal_test_account, false) IS FALSE
    AND ds.renewal_id IS NULL AND (ds.submission_scope IS NULL OR ds.submission_scope = 'registration');

  RETURN jsonb_build_object(
    'is_development_or_test_environment', _test_environment,
    'seed_batch', _batch_name,
    'total_seeded_organizations', _organizations,
    'expected_total', 84,
    'year_breakdown', jsonb_build_object('2024', _year_2024, '2025', _year_2025, '2026', _year_2026),
    'budget_breakdown', jsonb_build_object('awaiting_release', _awaiting, 'budget_released', _released,
      'completed', _completed, 'liquidated_reports', _liquidated),
    'registration_breakdown', jsonb_build_object(
      'packets', _packets, 'document_records', _documents,
      'required_documents_per_organization', _required,
      'organizations_complete', _complete, 'missing_requirements', _missing,
      'duplicate_requirements', _duplicates,
      'mapped_seed_assets', _mapped,
      'asset_mapping_complete', _required > 0 AND _mapped = _required,
      'renewal_test_organization_excluded', true
    ),
    'last_seeded_at', _last_seeded
  );
END;
$function$;
REVOKE EXECUTE ON FUNCTION public.admin_get_yorp_sample_dataset_status(text,text) FROM PUBLIC;

CREATE OR REPLACE FUNCTION public.enforce_accreditation_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.term_number IS DISTINCT FROM new.term_number
       OR old.start_date IS DISTINCT FROM new.start_date
       OR old.end_date IS DISTINCT FROM new.end_date
       OR old.certificate_urn IS DISTINCT FROM new.certificate_urn
       OR old.approved_by IS DISTINCT FROM new.approved_by
       OR old.approved_at IS DISTINCT FROM new.approved_at
       OR old.created_at IS DISTINCT FROM new.created_at
       OR old.is_legacy_inferred IS DISTINCT FROM new.is_legacy_inferred THEN

      RAISE EXCEPTION 'Historical accreditation term fields are immutable.';
    END IF;

    -- Revocation immutability rules:
    IF old.revoked_at IS NOT NULL AND new.revoked_at IS DISTINCT FROM old.revoked_at THEN
      RAISE EXCEPTION 'Accreditation revocation timestamp is immutable once set.';
    END IF;

    IF old.revocation_reason IS NOT NULL AND new.revocation_reason IS DISTINCT FROM old.revocation_reason THEN
      RAISE EXCEPTION 'Accreditation revocation reason is immutable once set.';
    END IF;

    IF new.status <> 'revoked' AND new.revoked_at IS NOT NULL THEN
      RAISE EXCEPTION 'Non-revoked accreditation terms cannot have a revocation timestamp.';
    END IF;

    -- Valid status transitions only:
    IF old.status = 'superseded' AND new.status <> 'superseded' THEN
      RAISE EXCEPTION 'A superseded accreditation term cannot be reactivated or altered.';
    END IF;

    IF old.status = 'revoked' AND new.status <> 'revoked' THEN
      RAISE EXCEPTION 'A revoked accreditation term cannot be reactivated.';
    END IF;

    IF old.status <> 'revoked' AND new.status = 'revoked' THEN
      IF new.revoked_at IS NULL THEN
        new.revoked_at := clock_timestamp();
      END IF;
    END IF;

    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    RAISE EXCEPTION 'Accreditation terms in the authoritative ledger cannot be deleted.';
  END IF;

  RETURN new;
END;
$function$;

CREATE OR REPLACE FUNCTION public.enforce_renewal_terminal_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF tg_op = 'UPDATE' THEN
    IF old.status IN ('approved', 'rejected') THEN
      RAISE EXCEPTION 'Terminal renewal records cannot be modified.';
    END IF;
    RETURN new;
  END IF;

  IF tg_op = 'DELETE' THEN
    IF current_setting('app.allow_org_deletion', true) = 'true' THEN
      RETURN old;
    END IF;
    IF old.status IN ('approved', 'rejected') THEN
      RAISE EXCEPTION 'Terminal renewal records cannot be deleted.';
    END IF;
    RETURN old;
  END IF;

  RETURN new;
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_organization_identity_privileges()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin

 -- Fixture markers are frozen in production, including through SECURITY DEFINER callers.
 -- No editable profile field, custom GUC, JWT claim, or Admin token bypasses this check.
 if tg_op='INSERT' then
   if coalesce(new.is_renewal_test_account,false) or coalesce(new.is_seeded_sample_data,false)
     or new.seed_batch is not null or new.seed_source_year is not null
     or new.seed_source_record_number is not null then
     raise exception 'Production fixture markers cannot be created.' using errcode='42501';
   end if;
 elsif row(new.is_renewal_test_account,new.is_seeded_sample_data,new.seed_batch,new.seed_source_year,new.seed_source_record_number)
   is distinct from row(old.is_renewal_test_account,old.is_seeded_sample_data,old.seed_batch,old.seed_source_year,old.seed_source_record_number) then
   raise exception 'Production fixture markers are immutable.' using errcode='42501';
 end if;
 if current_user not in ('postgres','supabase_admin','service_role') then
   if tg_op='INSERT' then
     new.created_at:=clock_timestamp();
     if new.profile_status::text in ('verified','suspended_inactive') or new.verified_at is not null
       or new.urn_review_status::text not in ('pending','not_applicable') or new.verification_method is not null
       or new.urn_reviewed_by is not null or new.urn_reviewed_at is not null
       or nullif(trim(new.urn_admin_remarks),'') is not null
       or nullif(trim(new.internal_notes),'') is not null then
       raise exception 'Organization verification requires an authorized server review.';
     end if;
   elsif new.user_id is distinct from old.user_id
     or new.created_at is distinct from old.created_at
     or (new.profile_status is distinct from old.profile_status and new.profile_status::text in ('verified','suspended_inactive'))
     or new.verified_at is distinct from old.verified_at
     or new.urn_review_status is distinct from old.urn_review_status
     or new.verification_method is distinct from old.verification_method
     or new.urn_reviewed_by is distinct from old.urn_reviewed_by
     or new.urn_reviewed_at is distinct from old.urn_reviewed_at
     or new.urn_admin_remarks is distinct from old.urn_admin_remarks
     or new.internal_notes is distinct from old.internal_notes
     or ((old.urn_review_status::text='verified' or old.profile_status::text='verified' or old.verified_at is not null) and (new.urn is distinct from old.urn
       or new.urn_normalized is distinct from old.urn_normalized
       or new.organization_identifier_number is distinct from old.organization_identifier_number
       or new.registration_type is distinct from old.registration_type))
     or (old.profile_status::text='verified' and new.profile_status is distinct from old.profile_status) then
       raise exception 'Organization verification fields require an authorized server review.';
   end if;
 end if;
 return new;
end $function$;

CREATE SCHEMA ytrace_production_containment AUTHORIZATION postgres;
REVOKE ALL ON SCHEMA ytrace_production_containment FROM PUBLIC, anon, authenticated, service_role;
CREATE FUNCTION ytrace_production_containment.freeze_fixture_markers()
RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER
SET search_path = pg_catalog, pg_temp
AS $markers$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF coalesce(NEW.is_seeded_sample_data,false) OR NEW.seed_batch IS NOT NULL THEN
      RAISE EXCEPTION 'Production fixture markers cannot be created.' USING ERRCODE='42501';
    END IF;
  ELSIF ROW(NEW.is_seeded_sample_data,NEW.seed_batch) IS DISTINCT FROM ROW(OLD.is_seeded_sample_data,OLD.seed_batch) THEN
    RAISE EXCEPTION 'Production fixture markers are immutable.' USING ERRCODE='42501';
  END IF;
  RETURN NEW;
END;
$markers$;
REVOKE ALL ON FUNCTION ytrace_production_containment.freeze_fixture_markers() FROM PUBLIC, anon, authenticated, service_role;
CREATE TRIGGER a_production_fixture_markers_guard BEFORE INSERT OR UPDATE ON public.budget_requests
FOR EACH ROW EXECUTE FUNCTION ytrace_production_containment.freeze_fixture_markers();
CREATE TRIGGER a_production_fixture_markers_guard BEFORE INSERT OR UPDATE ON public.liquidation_reports
FOR EACH ROW EXECUTE FUNCTION ytrace_production_containment.freeze_fixture_markers();
CREATE TRIGGER a_production_fixture_markers_guard BEFORE INSERT OR UPDATE ON public.document_submissions
FOR EACH ROW EXECUTE FUNCTION ytrace_production_containment.freeze_fixture_markers();
CREATE TRIGGER a_production_fixture_markers_guard BEFORE INSERT OR UPDATE ON public.document_submission_files
FOR EACH ROW EXECUTE FUNCTION ytrace_production_containment.freeze_fixture_markers();

