rivilege":"EXECUTE"},{"grantee":"authenticated","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"},{"grantee":"service_role","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"50d5dcf06885fa593fe5355fc8892d69","owner":"postgres","signature":"validate_admin_session_token(text)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"0f5766e8fe835c30681dab0ea86571db","owner":"postgres","signature":"ytrace_identity.authorize_reviewer(text)","volatility":"v","security_definer":true},{"acl":[{"grantee":"postgres","grantor":"postgres","grantable":false,"privilege":"EXECUTE"}],"md5":"608aaefe8b604986f752ea289ebed5f5","owner":"postgres","signature":"ytrace_identity.has_retained_history(uuid)","volatility":"s","security_definer":true}],"migrations":{"count":163,"latest":"20261008174154","fingerprint":"380c842e791bfbcf5c7a939371e24738"}}$expected_catalog$::jsonb;
 _post jsonb := $expected_post$[{"signature":"admin_cleanup_yorp_sample_dataset(text,text)","name":"admin_cleanup_yorp_sample_dataset","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_ensure_renewal_test_account_profile(text)","name":"admin_ensure_renewal_test_account_profile","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_get_or_create_renewal_test_account(text)","name":"admin_get_or_create_renewal_test_account","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_prepare_renewal_test_scenario(text,integer,date)","name":"admin_prepare_renewal_test_scenario","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_reset_renewal_test_scenario(text)","name":"admin_reset_renewal_test_scenario","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_restore_renewal_test_scenario(text)","name":"admin_restore_renewal_test_scenario","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_seed_renewal_test_registration_documents(text)","name":"admin_seed_renewal_test_registration_documents","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_seed_yorp_sample_dataset(text,text)","name":"admin_seed_yorp_sample_dataset","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"admin_seed_yorp_sample_dataset_core(text,text)","name":"admin_seed_yorp_sample_dataset_core","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"diversify_yorp_seed_projects_and_budgets()","name":"diversify_yorp_seed_projects_and_budgets","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"rebalance_yorp_seed_reporting_quarters()","name":"rebalance_yorp_seed_reporting_quarters","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"repair_yorp_seeded_fixture_relationships(uuid,uuid,uuid,jsonb,text)","name":"repair_yorp_seeded_fixture_relationships","source_md5":"6d670f664473257d4bf0b98e127337d1","security_definer":false,"volatility":"v"},{"signature":"is_development_or_test_environment()","name":"is_development_or_test_environment","source_md5":"7d69bbf21ad55293e15c24da50eaaa11","security_definer":false,"volatility":"s"},{"signature":"admin_get_yorp_sample_dataset_status(text,text)","name":"admin_get_yorp_sample_dataset_status","source_md5":"5bc2f180ec6d55ad22598412c1472022","security_definer":true,"volatility":"v"},{"signature":"enforce_accreditation_immutability()","name":"enforce_accreditation_immutability","source_md5":"19f9ecf4571f21795abc9160661f51b6","security_definer":true,"volatility":"v"},{"signature":"enforce_renewal_terminal_immutability()","name":"enforce_renewal_terminal_immutability","source_md5":"dd7f062b7a42f5cbc3782e225cc04d7d","security_definer":true,"volatility":"v"},{"signature":"guard_organization_identity_privileges()","name":"guard_organization_identity_privileges","source_md5":"ebe6884dd019667b7ac127f627b993ce","security_definer":false,"volatility":"v"}]$expected_post$::jsonb;
 _actual jsonb; f jsonb; original_function jsonb; changed boolean;
BEGIN
 SELECT q.manifest INTO _actual FROM (-- Read-only production catalog manifest; contains fingerprints, never function bodies or credentials.
SELECT jsonb_build_object(
 'functions',(SELECT jsonb_agg(jsonb_build_object(
  'signature',p.oid::regprocedure::text,'md5',md5(pg_get_functiondef(p.oid)),
  'owner',pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'volatility',p.provolatile,
  'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) ORDER BY coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a LEFT JOIN pg_roles r ON r.oid=a.grantee)
 ) ORDER BY n.nspname,p.proname,p.oid::regprocedure::text)
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE (n.nspname='public' AND p.proname IN ('admin_approve_renewal','admin_cleanup_yorp_sample_dataset','admin_ensure_renewal_test_account_profile','admin_get_or_create_renewal_test_account','admin_get_yorp_sample_dataset_status','admin_prepare_renewal_test_scenario','admin_reset_renewal_test_scenario','admin_restore_renewal_test_scenario','admin_seed_renewal_test_registration_documents','admin_seed_yorp_sample_dataset','admin_seed_yorp_sample_dataset_core','calculate_organization_renewal_eligibility','delete_organization_account_canonical','diversify_yorp_seed_projects_and_budgets','enforce_accreditation_immutability','enforce_renewal_terminal_immutability','guard_organization_identity_privileges','guard_submitted_registration_document_edits','is_development_or_test_environment','promote_renewal_submission_files_for_review','rebalance_yorp_seed_reporting_quarters','repair_yorp_seeded_fixture_relationships','replace_organization_document_file','update_admin_document_submission_file_review','user_replace_document_submission_file','user_resubmit_renewal','user_start_or_get_renewal_draft','user_submit_renewal','validate_admin_session_token'))
 OR (n.nspname='ytrace_identity' AND p.proname IN ('authorize_reviewer','has_retained_history'))),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'owner',pg_get_userbyid(c.relowner),'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,
 'acl',(SELECT jsonb_agg(jsonb_build_object('grantee',coalesce(r.rolname,'PUBLIC'),'privilege',a.privilege_type,'grantable',a.is_grantable,'grantor',pg_get_userbyid(a.grantor)) ORDER BY coalesce(r.rolname,'PUBLIC'),a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a LEFT JOIN pg_roles r ON r.oid=a.grantee),
 'columns',(SELECT md5(string_agg(a.attname||':'||format_type(a.atttypid,a.atttypmod)||':'||a.attnotnull||':'||coalesce(pg_get_expr(d.adbin,d.adrelid),''),E'\n' ORDER BY a.attnum)) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT md5(coalesce(string_agg(con.conname||':'||pg_get_constraintdef(con.oid),E'\n' ORDER BY con.conname),'')) FROM pg_constraint con WHERE con.conrelid=c.oid),
 'triggers',(SELECT md5(coalesce(string_agg(t.tgname||':'||t.tgenabled::text||':'||pg_get_triggerdef(t.oid),E'\n' ORDER BY t.tgname),'')) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal AND t.tgname <> 'a_production_fixture_markers_guard')
 ) ORDER BY n.nspname,c.relname)
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE (n.nspname='public' AND c.relname IN ('organization_profiles','organization_accreditations','organization_renewals','document_submissions','document_submission_files','admin_accounts','admin_sessions','roles','budget_requests','liquidation_reports'))
 OR (n.nspname='supabase_migrations' AND c.relname='schema_migrations')),
 'policies',(SELECT md5(coalesce(string_agg(schemaname||':'||tablename||':'||policyname||':'||roles::text||':'||cmd||':'||permissive||':'||coalesce(qual,'')||':'||coalesce(with_check,''),E'\n' ORDER BY schemaname,tablename,policyname),'')) FROM pg_policies WHERE schemaname IN ('public','storage')),
 'roles',(SELECT jsonb_agg(jsonb_build_object('name',r.rolname,'inherit',r.rolinherit,'bypass_rls',r.rolbypassrls,'superuser',r.rolsuper,'memberships',(SELECT coalesce(jsonb_agg(parent.rolname ORDER BY parent.rolname),'[]'::jsonb) FROM pg_auth_members m JOIN pg_roles parent ON parent.oid=m.roleid WHERE m.member=r.oid)) ORDER BY r.rolname) FROM pg_roles r WHERE r.rolname IN ('anon','authenticated','service_role','postgres','authenticator')),
 'migrations',(SELECT jsonb_build_object('count',count(*),'latest',max(version),'fingerprint',md5(coalesce(string_agg(version||':'||coalesce(name,''),E'\n' ORDER BY version),''))) FROM supabase_migrations.schema_migrations)
) AS manifest) q;
 IF (_actual-'functions') IS DISTINCT FROM (_expected-'functions') THEN
   RAISE EXCEPTION 'Unrelated catalog, permissions, or migration state changed';
 END IF;
 FOR f IN SELECT value FROM jsonb_array_elements(_actual->'functions') LOOP
   SELECT value INTO original_function FROM jsonb_array_elements(_expected->'functions') WHERE value->>'signature'=f->>'signature';
   SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(_post) x WHERE x->>'signature'=f->>'signature') INTO changed;
   IF NOT changed AND f IS DISTINCT FROM original_function THEN
     RAISE EXCEPTION 'Normal business function changed: %',f->>'signature';
   END IF;
 END LOOP;
 FOR f IN SELECT value FROM jsonb_array_elements(_post) LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure(f->>'signature')
      AND pg_get_userbyid(p.proowner)='postgres' AND md5(p.prosrc)=f->>'source_md5'
      AND p.prosecdef=(f->>'security_definer')::boolean AND p.provolatile::text=f->>'volatility') THEN
     RAISE EXCEPTION 'Containment replacement differs: %',f->>'signature';
   END IF;
 END LOOP;
 FOR f IN SELECT value FROM jsonb_array_elements(_post) WHERE value->>'name' IN ('admin_cleanup_yorp_sample_dataset','admin_ensure_renewal_test_account_profile','admin_get_or_create_renewal_test_account','admin_prepare_renewal_test_scenario','admin_reset_renewal_test_scenario','admin_restore_renewal_test_scenario','admin_seed_renewal_test_registration_documents','admin_seed_yorp_sample_dataset','admin_seed_yorp_sample_dataset_core','diversify_yorp_seed_projects_and_budgets','rebalance_yorp_seed_reporting_quarters','repair_yorp_seeded_fixture_relationships') LOOP
   IF has_function_privilege('anon',to_regprocedure(f->>'signature'),'EXECUTE')
      OR has_function_privilege('authenticated',to_regprocedure(f->>'signature'),'EXECUTE')
      OR has_function_privilege('service_role',to_regprocedure(f->>'signature'),'EXECUTE')
      OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=to_regprocedure(f->>'signature') AND a.grantee=0 AND a.privilege_type='EXECUTE') THEN
     RAISE EXCEPTION 'Disabled function still has API execution privilege: %',f->>'signature';
   END IF;
 END LOOP;
 IF public.is_development_or_test_environment() IS DISTINCT FROM false THEN
   RAISE EXCEPTION 'Production environment must always fail closed';
 END IF;
 -- Custom Admin sessions use anon/authenticated transport; token + active Super Admin role is checked in SQL.
 IF NOT has_function_privilege('anon','public.admin_get_yorp_sample_dataset_status(text,text)','EXECUTE')
 OR NOT has_function_privilege('authenticated','public.admin_get_yorp_sample_dataset_status(text,text)','EXECUTE') THEN
   RAISE EXCEPTION 'Retained custom Admin status transport grant lost';
 END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('ytrace_production_containment.freeze_fixture_markers()')
   AND pg_get_userbyid(p.proowner)='postgres' AND NOT p.prosecdef AND md5(p.prosrc)='73223cc8d66adfa64e1c1877249d19b3'
   AND p.proconfig=ARRAY['search_path=pg_catalog, pg_temp']::text[]) THEN
   RAISE EXCEPTION 'Fixture guard body or execution context differs';
 END IF;
 IF (SELECT count(*) FROM pg_trigger WHERE tgname='a_production_fixture_markers_guard' AND NOT tgisinternal) <> 4 THEN
   RAISE EXCEPTION 'Fixture guard trigger count differs';
 END IF;
 FOR f IN SELECT to_jsonb(x) FROM (VALUES ('budget_requests'),('liquidation_reports'),('document_submissions'),('document_submission_files')) x(table_name) LOOP
   IF NOT EXISTS(SELECT 1 FROM pg_trigger t WHERE t.tgrelid=to_regclass('public.'||(f->>'table_name'))
     AND t.tgname='a_production_fixture_markers_guard' AND t.tgenabled='O'
     AND pg_get_triggerdef(t.oid)='CREATE TRIGGER a_production_fixture_markers_guard BEFORE INSERT OR UPDATE ON public.'||(f->>'table_name')||' FOR EACH ROW EXECUTE FUNCTION ytrace_production_containment.freeze_fixture_markers()') THEN
     RAISE EXCEPTION 'Fixture marker trigger differs: %',f->>'table_name';
   END IF;
 END LOOP;
 IF has_schema_privilege('anon','ytrace_production_containment','USAGE')
   OR has_schema_privilege('authenticated','ytrace_production_containment','USAGE')
   OR has_schema_privilege('service_role','ytrace_production_containment','USAGE')
   OR has_function_privilege('anon','ytrace_production_containment.freeze_fixture_markers()','EXECUTE')
   OR has_function_privilege('authenticated','ytrace_production_containment.freeze_fixture_markers()','EXECUTE')
   OR has_function_privilege('service_role','ytrace_production_containment.freeze_fixture_markers()','EXECUTE') THEN
   RAISE EXCEPTION 'Private fixture guard permissions differ';
 END IF;
END $containment_postconditions$;

INSERT INTO supabase_migrations.schema_migrations(version,name,statements)
VALUES ('20261011230000','production_test_utility_containment',ARRAY['Standalone reviewed test-utility containment; see separately recorded candidate SHA-256.']);
COMMIT;
